CREATE FUNCTION public.guard_visit_update() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.role()='authenticated' AND NOT public.has_club_role('directiva') THEN IF (to_jsonb(NEW)-'anulada') IS DISTINCT FROM (to_jsonb(OLD)-'anulada') OR NOT NEW.anulada OR OLD.fecha_hora < now()-interval '10 minutes' THEN RAISE EXCEPTION 'Solo puedes anular visitas propias de los últimos 10 minutos'; END IF; END IF; RETURN NEW; END $$; CREATE TRIGGER visitas_update_guard BEFORE UPDATE ON public.visitas FOR EACH ROW EXECUTE FUNCTION public.guard_visit_update(); REVOKE ALL ON FUNCTION public.guard_visit_update() FROM PUBLIC;
CREATE FUNCTION public.estado_sesion_socia() RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.profiles; s public.socios; BEGIN IF NOT public.has_club_role('socia') THEN RETURN NULL; END IF; SELECT * INTO p FROM public.profiles WHERE id=auth.uid(); IF NOT FOUND THEN RETURN 'movido'; END IF; SELECT * INTO s FROM public.socios WHERE id=p.socio_id; IF s.estado='desactivada' THEN RETURN 'desactivada'; END IF; IF s.dispositivo_id IS DISTINCT FROM p.dispositivo_id THEN RETURN 'movido'; END IF; RETURN 'ok'; END $$; REVOKE ALL ON FUNCTION public.estado_sesion_socia() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.estado_sesion_socia() TO authenticated;
CREATE FUNCTION public.visit_names_today() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF public.mi_patrocinador() IS NULL AND NOT public.has_club_role('directiva') THEN RAISE EXCEPTION 'No autorizado'; END IF; RETURN (SELECT coalesce(jsonb_object_agg(s.id,jsonb_build_object('nombre',s.nombre,'numero',s.numero_socio)),'{}') FROM public.socios s WHERE EXISTS(SELECT 1 FROM public.visitas v WHERE v.socio_id=s.id AND (v.patrocinador_id=public.mi_patrocinador() OR public.has_club_role('directiva')) AND v.fecha=(now() AT TIME ZONE 'Europe/Madrid')::date)); END $$; REVOKE ALL ON FUNCTION public.visit_names_today() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.visit_names_today() TO authenticated;